using Z=mpz_class;
struct Mat{int n;std::vector<Z>a;Mat(int d=0):n(d),a(d*d){} Z& at(int i,int j){return a[i*n+j];}const Z& at(int i,int j)const{return a[i*n+j];}};
struct Small{int n;std::vector<long>a;Small(int d=0):n(d),a(d*d){}long&at(int i,int j){return a[i*n+j];}long at(int i,int j)const{return a[i*n+j];}};
long checked(__int128 x){if(x<std::numeric_limits<long>::min()||x>std::numeric_limits<long>::max())throw std::runtime_error("local integer overflow");return (long)x;}
Small smul(const Small&A,const Small&B){Small C(A.n);for(int i=0;i<A.n;i++)for(int j=0;j<A.n;j++){__int128 s=0;for(int k=0;k<A.n;k++)s+=(__int128)A.at(i,k)*B.at(k,j);C.at(i,j)=checked(s);}return C;}
Mat convert(const Small&A){Mat B(A.n);for(size_t i=0;i<A.a.size();i++)B.a[i]=A.a[i];return B;}
Mat eye(int n){Mat A(n);for(int i=0;i<n;i++)A.at(i,i)=1;return A;}
unsigned long long muls=0;
Mat mul(const Mat&A,const Mat&B){if(A.n!=B.n)throw std::runtime_error("dim");muls++;Mat C(A.n);for(int i=0;i<A.n;i++)for(int k=0;k<A.n;k++)if(A.at(i,k)!=0)for(int j=0;j<A.n;j++)if(B.at(k,j)!=0)mpz_addmul(C.at(i,j).get_mpz_t(),A.at(i,k).get_mpz_t(),B.at(k,j).get_mpz_t());return C;}
Mat add(const Mat&A,const Mat&B,int s=1){Mat C(A.n);for(size_t i=0;i<A.a.size();i++)C.a[i]=A.a[i]+s*B.a[i];return C;}
Z tr(const Mat&A){Z z;for(int i=0;i<A.n;i++)z+=A.at(i,i);return z;}
Z trprod(const Mat&A,const Mat&B){Z z;for(int i=0;i<A.n;i++)for(int j=0;j<A.n;j++)mpz_addmul(z.get_mpz_t(),A.at(i,j).get_mpz_t(),B.at(j,i).get_mpz_t());return z;}
bool eq(const Mat&A,const Mat&B){return A.n==B.n&&A.a==B.a;}
Mat power(Mat A,int n){Mat P=eye(A.n);while(n){if(n&1)P=mul(P,A);n>>=1;if(n)A=mul(A,A);}return P;}
void require(bool b,const std::string&s){if(!b)throw std::runtime_error(s);}
struct Term{int x,y,c;};
std::vector<Term> terms(const std::vector<int>&a,int n){std::vector<Term> out;for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(a[i*n+j])out.push_back({i,j,a[i*n+j]});return out;}
std::vector<int> imul(const std::vector<int>&a,const std::vector<int>&b,int n){std::vector<int>c(n*n);for(int i=0;i<n;i++)for(int k=0;k<n;k++)for(int j=0;j<n;j++)c[i*n+j]+=a[i*n+k]*b[k*n+j];return c;}
struct Ops{std::vector<Term>id,h,u,v;};
Ops operators(){std::vector<int>h(81),id(9);for(int x=0;x<3;x++)id[3*x+x]=1;for(int s=0;s<3;s++)for(int t=0;t<3;t++)for(int u=0;u<3;u++)for(int v=0;v<3;v++){int x=3*s+t,y=3*u+v;h[9*x+y]=(s==u&&t==v)?(s-1)*(t-1):((s+t==u+v&&abs(s-u)==1)?1:0);}auto h2=imul(h,h,9);auto a=h,b=h,c=h;for(int i=0;i<9;i++){a[9*i+i]+=2;b[9*i+i]+=1;c[9*i+i]-=1;}auto poly=imul(imul(a,b,9),c,9);for(int x:poly)require(x==0,"local h polynomial");std::vector<int>hl(729),hr(729);for(int i=0;i<27;i++)for(int j=0;j<27;j++){int ia=i/9,ib=(i/3)%3,ic=i%3,ja=j/9,jb=(j/3)%3,jc=j%3;if(ic==jc)hl[27*i+j]=h[9*(3*ia+ib)+(3*ja+jb)];if(ia==ja)hr[27*i+j]=h[9*(3*ib+ic)+(3*jb+jc)];}auto v=imul(hl,hr,27),w=imul(hr,hl,27);for(int i=0;i<729;i++)v[i]+=w[i];for(int i=0;i<9;i++)for(int j=0;j<9;j++)require(h[9*i+j]==h[9*j+i]&&h2[9*i+j]==h2[9*j+i],"local two-site Hermiticity");for(int i=0;i<27;i++)for(int j=0;j<27;j++)require(v[27*i+j]==v[27*j+i],"adjacent Hermiticity");return{terms(id,3),terms(h,9),terms(h2,9),terms(v,27)};}
struct Model{int d;std::vector<Small>A;std::vector<int>charges;};
Model d26(){std::vector<int>ell={1,1,1,1,3,3,3,5},diag={-289,-84,-9,33,-22,27,71,-11};std::map<std::pair<int,int>,int>p={{{0,4},-11},{{0,5},-35},{{0,6},-28},{{1,4},-23},{{1,5},16},{{1,6},-49},{{2,4},-6},{{2,5},-25},{{2,6},-20},{{3,4},-34},{{3,5},9},{{3,6},-32},{{4,7},1},{{5,7},2},{{6,7},-16}};std::vector<std::pair<int,int>>labels;for(int a=0;a<8;a++)for(int m=-ell[a];m<=ell[a];m+=2)labels.push_back({a,m});Model M{26,{Small(26),Small(26),Small(26)},{}};for(auto q:labels)M.charges.push_back(q.second);for(int i=0;i<26;i++)for(int j=0;j<26;j++){auto[a,m]=labels[i];auto[b,k]=labels[j];int dif=k-m;if(dif%2)continue;int s=dif/2;if(s<-1||s>1)continue;int l=ell[a],r=(l+m)/2,val=0;if(a==b)val=diag[a]*(s==-1?2*(l-r+1):s==0?m:-(r+1));else if(p.count({a,b}))val=p[{a,b}]*(s==-1?2*(l+1-r)*(l+2-r):s==0?2*(r+1)*(l-r+1):(r+1)*(r+2));else if(p.count({b,a}))val=-p[{b,a}]*(s==-1?2:s==0?-2:1);M.A[s+1].at(i,j)=val;require(labs(val)<=1156,"A bound");}return M;}
std::vector<std::vector<Mat>> words(const Model&M){std::vector<std::vector<Small>>w(4);Small id(M.d);for(int i=0;i<M.d;i++)id.at(i,i)=1;w[0].push_back(id);for(int k=1;k<=3;k++)for(auto&b:w[k-1])for(auto&a:M.A)w[k].push_back(smul(b,a));std::vector<std::vector<Mat>>g(4);for(int k=0;k<=3;k++)for(auto&a:w[k])g[k].push_back(convert(a));return g;}
Mat insertion(const std::vector<std::pair<int,int>>&ids,const std::vector<Mat>&w,const std::vector<Term>&ts){Mat E(ids.size());for(size_t a=0;a<ids.size();a++)for(size_t b=0;b<ids.size();b++){auto[i,j]=ids[a];auto[k,l]=ids[b];Z&z=E.at(a,b);for(auto&t:ts){const Z&x=w[t.x].at(i,k);const Z&y=w[t.y].at(j,l);if(x==0||y==0)continue;for(int v=0;v<abs(t.c);v++)if(t.c>0)mpz_addmul(z.get_mpz_t(),x.get_mpz_t(),y.get_mpz_t());else mpz_submul(z.get_mpz_t(),x.get_mpz_t(),y.get_mpz_t());}}return E;}
struct Result{Z norm,h,h2,b2,bmean,same,adj,disj,wrongSign;};
void amplitude_dfs(const std::vector<Mat>&A,const Mat&P,int depth,int index,std::map<int,std::vector<Z>>&vs){if(depth==4||depth==6)vs[depth][index]=tr(P);if(depth==6)return;for(int s=0;s<3;s++)amplitude_dfs(A,mul(P,A[s]),depth+1,3*index+s,vs);}
std::map<int,Result> direct(const Model&M){std::map<int,std::vector<Z>>vs;vs[4].resize(81);vs[6].resize(729);std::vector<Mat>A;for(auto&a:M.A)A.push_back(convert(a));amplitude_dfs(A,eye(M.d),0,0,vs);std::map<int,Result>out;for(int L:{4,6}){auto&v=vs[L];std::vector<Z>hv(v.size()),bv(v.size());std::vector<int>pw(L);pw[L-1]=1;for(int j=L-2;j>=0;j--)pw[j]=3*pw[j+1];for(int ind=0;ind<(int)v.size();ind++)if(v[ind]!=0)for(int j=0;j<L;j++){int k=(j+1)%L;int a=(ind/pw[j])%3-1,b=(ind/pw[k])%3-1;int sg=j%2?-1:1;hv[ind]+=a*b*v[ind];bv[ind]+=sg*a*b*v[ind];if(a<1&&b>-1){int tar=ind+pw[j]-pw[k];hv[tar]+=v[ind];bv[tar]+=sg*v[ind];}if(a>-1&&b<1){int tar=ind-pw[j]+pw[k];hv[tar]+=v[ind];bv[tar]+=sg*v[ind];}}Result r;for(size_t i=0;i<v.size();i++){r.norm+=v[i]*v[i];r.h+=v[i]*hv[i];r.h2+=hv[i]*hv[i];r.b2+=bv[i]*bv[i];r.bmean+=v[i]*bv[i];}require(r.norm>0&&r.bmean==0,"direct norm or staggered expectation");require(r.h2*r.norm>=r.h*r.h,"direct variance");out[L]=r;}return out;}
struct BlockPower{Mat p,r;int sg;};
BlockPower compose(const BlockPower&a,const BlockPower&b){return{mul(a.p,b.p),add(mul(a.p,b.r),mul(a.r,b.p),b.sg),a.sg*b.sg};}
BlockPower bpower(const Mat&T,const Mat&O,int N,int z){BlockPower a{eye(T.n),Mat(T.n),1},b{T,O,z};while(N){if(N&1)a=compose(a,b);N>>=1;if(N)b=compose(b,b);}return a;}
void abstract_binary(){Mat T(2),O(2);T.a={2,1,3,-1};O.a={1,2,-1,0};for(int z:{-1,1})for(int n=0;n<=12;n++){auto B=bpower(T,O,n,z);Mat K(4);for(int i=0;i<2;i++)for(int j=0;j<2;j++){K.at(i,j)=T.at(i,j);K.at(i,j+2)=O.at(i,j);K.at(i+2,j+2)=z*T.at(i,j);}auto P=power(K,n);for(int i=0;i<2;i++)for(int j=0;j<2;j++){require(B.p.at(i,j)==P.at(i,j),"abstract upper diagonal");require(B.sg*B.p.at(i,j)==P.at(i+2,j+2),"abstract lower diagonal");require(B.r.at(i,j)==P.at(i,j+2),"abstract upper-right sign");}}}
std::map<int,Result> contracted(const Model&M,const Ops&op,std::ifstream*pin,std::ofstream*save){auto w=words(M);std::map<int,std::vector<std::pair<int,int>>>groups;for(int i=0;i<M.d;i++)for(int j=0;j<M.d;j++)groups[M.charges.empty()?0:M.charges[i]-M.charges[j]].push_back({i,j});if(pin){int n;*pin>>n;require(n==(int)groups.size(),"pinned group count");}if(save)*save<<groups.size()<<"\n";std::map<int,Result>out;for(auto&[charge,ids]:groups){int d=ids.size();Mat T=insertion(ids,w[1],op.id),O=insertion(ids,w[2],op.h);if(pin){int q,n;*pin>>q>>n;require(q==charge&&n==d,"pinned block index");Z x;for(auto&A:{&T,&O})for(auto&v:A->a){*pin>>x;require((bool)*pin&&x==v,"pinned transfer entry");}}Mat U=insertion(ids,w[2],op.u),V=insertion(ids,w[3],op.v);if(save){*save<<charge<<" "<<d<<"\n";for(auto&A:{&T,&O,&U,&V})for(int i=0;i<d;i++){for(int j=0;j<d;j++)*save<<A->at(i,j)<<" ";*save<<"\n";}}Mat T2=mul(T,T),T3=mul(T2,T),T4=mul(T2,T2),T6=mul(T3,T3),TO=mul(T,O),OT=mul(O,T),T2O=mul(T2,O);Mat R2minus=add(TO,OT,-1),R2plus=add(TO,OT);Mat R3minus=add(T2O,mul(R2minus,T),-1),R3plus=add(T2O,mul(R2plus,T));Z eplus=trprod(T2O,O)+trprod(O,T2O)+trprod(TO,TO),eminus=trprod(T2O,O)+trprod(O,T2O)-trprod(TO,TO);require(trprod(R3plus,O)==eplus&&trprod(R3minus,O)==eminus,"binary vs displacement convolution");for(int L:{4,6}){Result&r=out[L];r.norm+=tr(L==4?T4:T6);r.h+=L*trprod(L==4?T2:T4,O);Z same=trprod(L==4?T2:T4,U),adj=trprod(L==4?T:T3,V),dp=trprod(L==4?O:R3plus,O),dm=trprod(L==4?O:R3minus,O);r.same+=same;r.adj+=adj;r.disj+=dm;r.h2+=L*(same+adj+dp);r.b2+=L*(same-adj+dm);r.wrongSign+=L*(same+adj+dm);}std::cerr<<"block="<<charge<<" side="<<d<<" cpu="<<double(clock())/CLOCKS_PER_SEC<<"\n";}
return out;}
void check_results(const std::string&name,const std::map<int,Result>&a,const std::map<int,Result>&b,std::array<bool,6>&bad){for(int L:{4,6}){auto&x=a.at(L);auto&y=b.at(L);require(x.norm==y.norm&&x.h==y.h&&x.h2==y.h2&&x.b2==y.b2,"direct/transfer mismatch "+name+" L"+std::to_string(L));bad[0]|=y.b2!=L*y.b2;bad[1]|=y.b2!=y.b2/L;bad[2]|=y.b2*y.norm!=y.b2;bad[3]|=y.wrongSign!=y.b2;bad[4]|=(y.b2-L*y.adj)!=y.b2;bad[5]|=(y.b2-L*y.disj)!=y.b2;std::cout<<"CASE "<<name<<" L="<<L<<"\nN="<<x.norm<<"\nH="<<x.h<<"\nH2="<<x.h2<<"\nB2="<<x.b2<<"\nSTAGGERED_MEAN="<<x.bmean<<"\nPASS\n";}}
void guard(){rlimit c,m;getrlimit(RLIMIT_CPU,&c);getrlimit(RLIMIT_AS,&m);require(c.rlim_cur==14&&c.rlim_max==14,"CPU hard guard");require(m.rlim_cur==256ul*1024*1024&&m.rlim_max==m.rlim_cur,"memory guard");cpu_set_t s;CPU_ZERO(&s);require(sched_getaffinity(0,sizeof(s),&s)==0&&CPU_COUNT(&s)==1&&CPU_ISSET(4,&s),"CPU4 affinity");struct sigaction a;sigaction(SIGXCPU,nullptr,&a);sigset_t blocked;sigprocmask(SIG_BLOCK,nullptr,&blocked);require(a.sa_handler==SIG_DFL&&!sigismember(&blocked,SIGXCPU),"SIGXCPU guard");int pd;prctl(PR_GET_PDEATHSIG,&pd);require(pd==SIGKILL,"parent death guard");std::cerr<<"GUARDS CPU=14 AS=256MiB AFFINITY=4\n";}
int main(int argc,char**argv){try{guard();require(argc==3,"arguments pinned-input output-blocks");abstract_binary();Ops op=operators();Model M=d26();std::cerr<<"START direct D26 cpu="<<double(clock())/CLOCKS_PER_SEC<<"\n";auto a=direct(M);std::cerr<<"START transfer D26 cpu="<<double(clock())/CLOCKS_PER_SEC<<"\n";std::ifstream pin(argv[1]);std::ofstream save(argv[2]);require((bool)pin&&(bool)save,"file open");auto b=contracted(M,op,&pin,&save);save.close();std::array<bool,6>bad{};check_results("D26",a,b,bad);Model S{2,{Small(2),Small(2),Small(2)},{}};S.A[0].a={1,2,0,1};S.A[1].a={2,0,1,-1};S.A[2].a={0,1,-2,2};auto sa=direct(S),sb=contracted(S,op,nullptr,nullptr);check_results("D2",sa,sb,bad);for(bool p:bad)require(p,"adversarial mutation not detected");std::cout<<"ABSTRACT_BLOCK_TESTS=26\nADVERSARIAL_REJECTIONS=6\nALL_FIXTURES_PASS\n";rusage u;getrusage(RUSAGE_SELF,&u);std::cerr<<"FINAL cpu="<<double(clock())/CLOCKS_PER_SEC<<" rss_kib="<<u.ru_maxrss<<" matrix_multiplications="<<muls<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"FAILED "<<e.what()<<" cpu="<<double(clock())/CLOCKS_PER_SEC<<"\n";return 2;}}
